-- Parity test for Cognos report Customer_Cost_of_Service (cluster BIL_032, 1 runs/day)
-- Generated by SemLift 1.0.0; tolerance +/-0.5% on totals
WITH cognos AS (
    SELECT dt.FISCAL_YEAR AS fiscal_year, dt.MONTH_NAME AS month_name, customer.CUSTOMER_SEGMENT AS customer_segment, SUM(billing.BILL_AMOUNT) AS total_bill_amount, SUM(billing.DEMAND_CHARGE) AS total_demand_charge, SUM(billing.ENERGY_CHARGE) AS total_energy_charge
    FROM CORE.FCT_BILLING billing
    JOIN CORE.DIM_DATE dt ON billing.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_METER meter ON billing.METER_ID = meter.METER_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_BILLING_REVENUE
        DIMENSIONS dt.fiscal_year, dt.month_name, customer.customer_segment
        METRICS billing.total_bill_amount, billing.total_demand_charge, billing.total_energy_charge
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_bill_amount) AS cognos_total_bill_amount, SUM(s.total_bill_amount) AS semantic_total_bill_amount,
    IFF(ABS(COALESCE(SUM(s.total_bill_amount), 0) - COALESCE(SUM(c.total_bill_amount), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_bill_amount), 0)), 'PASS', 'FAIL') AS status_total_bill_amount,
    SUM(c.total_demand_charge) AS cognos_total_demand_charge, SUM(s.total_demand_charge) AS semantic_total_demand_charge,
    IFF(ABS(COALESCE(SUM(s.total_demand_charge), 0) - COALESCE(SUM(c.total_demand_charge), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_demand_charge), 0)), 'PASS', 'FAIL') AS status_total_demand_charge,
    SUM(c.total_energy_charge) AS cognos_total_energy_charge, SUM(s.total_energy_charge) AS semantic_total_energy_charge,
    IFF(ABS(COALESCE(SUM(s.total_energy_charge), 0) - COALESCE(SUM(c.total_energy_charge), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_energy_charge), 0)), 'PASS', 'FAIL') AS status_total_energy_charge
FROM cognos c
FULL OUTER JOIN semantic s ON c.fiscal_year IS NOT DISTINCT FROM s.fiscal_year AND c.month_name IS NOT DISTINCT FROM s.month_name AND c.customer_segment IS NOT DISTINCT FROM s.customer_segment;
